B=A.copy()
for r in range(A.shape[0]):
    cs=np.where(A[r]==0)[0]
    if len(cs)>=2:
        for c in range(cs.min()+1,cs.max()):
            if A[r,c]!=0: B[r,c]=3
for c in range(A.shape[1]):
    rs=np.where(A[:,c]==0)[0]
    if len(rs)>=2:
        for r in range(rs.min()+1,rs.max()):
            if A[r,c]!=0: B[r,c]=3
print('\n'.join(' '.join(map(str,row)) for row in B.tolist()))
